#include <map>
#include <print>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> words = {"python", "java", "python", "c++", "python", "java"};
    std::map<std::string, int> freq;
    for (const auto& w : words) freq[w]++;            // 核心就这一行
    for (const auto& [word, count] : freq)
        std::println("{:<8} {} 次", word, count);
    // 比 vector 加 struct 那一版：少了 struct 定义、少了从头扫到尾的 find_word、少了那段 if 分叉，打印照旧

    std::map<char, int> chars;
    std::string s = "hello world";
    for (char c : s) chars[c]++;                       // 空格也照样记一笔
    std::println("l = {}", chars['l']);
    std::println("o = {}", chars['o']);
    return 0;
}

