#include <vector>

int main() {
    std::vector<std::string> words = {"python", "java"};
    std::map<std::string, int> freq;
    for (const auto& w : words) {
        if (freq.contains(w)) freq[w] = freq[w] + 1; else freq[w] = 1;
    }
    return 0;
}
